package api

import (
	"context"
	"net/http"
	"testing"

	"github.com/mellifera/mellifera/internal/scan"
)

// TestQA_RoutingDefaultDeny_BrowseGroup proves an unknown/empty role is denied
// 403 `forbidden` on BOTH the browse group (admin+client) and the admin group
// (admin-only) through the real mountV1Routes wiring. The admin control rows
// self-validate the wiring: an admitted role MUST reach the handler (browse ->
// 200, admin/status -> 503 with Status nil), so a 403 for unknown/empty is
// attributable to the gate firing, not a broken route (anti-tautology).
func TestQA_RoutingDefaultDeny_BrowseGroup(t *testing.T) {
	deps := Deps{
		AdminToken: adminToken,
		Store:      openAPIStore(t),
		Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
		// Status nil -> admin/status returns 503 for an admitted admin (the
		// control row), proving authZ passed without depending on the closure.
	}

	cases := []struct {
		name       string
		role       Role
		path       string
		wantStatus int
	}{
		// Control: admitted admin reaches both groups (validates the wiring).
		{"admin_control_browse", RoleAdmin, "/api/v1/libraries", http.StatusOK},
		{"admin_control_admin", RoleAdmin, "/api/v1/admin/status", http.StatusServiceUnavailable},
		// The gap: unknown/empty role must be denied on the BROWSE group too.
		{"empty_role_denied_browse", Role(""), "/api/v1/libraries", http.StatusForbidden},
		{"unknown_role_denied_browse", Role("superuser"), "/api/v1/libraries", http.StatusForbidden},
		// And on the admin group (default-deny holds on every group).
		{"empty_role_denied_admin", Role(""), "/api/v1/admin/status", http.StatusForbidden},
		{"unknown_role_denied_admin", Role("superuser"), "/api/v1/admin/status", http.StatusForbidden},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			h := gatingRouter(deps, tc.role)
			resp := doRequest(t, h, http.MethodGet, tc.path, "", "")
			defer resp.Body.Close()
			if resp.StatusCode != tc.wantStatus {
				t.Fatalf("role=%q %s: status = %d, want %d", tc.role, tc.path, resp.StatusCode, tc.wantStatus)
			}
			if tc.wantStatus == http.StatusForbidden {
				if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
					t.Fatalf("role=%q %s: error code = %q, want forbidden", tc.role, tc.path, eb.Error.Code)
				}
			}
		})
	}
}
